<?php use App\UI\UI as U; $s=$data['sample']; $active = count(array_filter($s['drivers'], fn($d) => $d['status'] === 'Active')); ?>
<?= U::heading('Driver registrations','Driver identity and station assignment metadata.',U::btn('Export registrations','','secondary','download',['data-export'=>'driver-registry'])) ?>
<div class="mb-5 grid grid-cols-2 gap-3 md:gap-4 lg:grid-cols-3 max-lg:[&>:last-child:nth-child(odd)]:col-span-2"><?= U::stat('Registered drivers',(string)count($s['drivers']),'users','blue','Across all stations','Drivers') ?><?= U::stat('Active',(string)$active,'check','green','Can be assigned trips','Active') ?><?= U::stat('Inactive',(string)(count($s['drivers'])-$active),'close','red','Not taking deliveries','Inactive') ?></div>
<section class="panel p-4 md:p-5"><div class="mb-4 grid gap-3 md:grid-cols-[1fr_240px]"><?= U::field('Search drivers','driver-search','','search',['icon'=>'search','data-search'=>'driver-registry','placeholder'=>'Driver name or assigned station']) ?><?= U::select('Account status','driver-status',['all'=>'All drivers','Active'=>'Active','Inactive'=>'Inactive'],'all',['data-filter-target'=>'driver-registry']) ?></div>
<div class="overflow-x-auto"><table id="driver-registry" class="data-table"><thead><tr><?php foreach(['Driver','Station','Contact','Vehicle','Registered','Status'] as $h): ?><th><?= $h ?></th><?php endforeach; ?></tr></thead><tbody><?php foreach($s['drivers'] as $d): ?><tr data-search-row data-filter-value="<?= U::e($d['status']) ?>"><td><span class="flex items-center gap-2.5"><span class="title-icon size-8"><?= U::icon('user','size-4') ?></span><strong><?= U::e($d['name']) ?></strong></span></td><td><span class="inline-flex items-center gap-1.5"><?= U::icon('store','size-4 text-water') ?><?= U::e($d['station']) ?></span></td><td><span class="inline-flex items-center gap-1.5 whitespace-nowrap"><?= U::icon('phone','size-4 text-muted') ?><?= U::e($d['phone']) ?></span></td><td><span class="inline-flex items-center gap-1.5"><?= U::icon('truck','size-4 text-muted') ?><?= U::e($d['vehicle']) ?></span></td><td class="whitespace-nowrap"><?= U::e($d['date']) ?></td><td><?= U::badge($d['status'],$d['status']==='Active'?'green':'gray') ?></td></tr><?php endforeach; ?></tbody></table><p data-empty hidden class="p-5 text-center text-muted">No registered drivers match.</p></div></section>
<div class="mt-5 flex items-start gap-3 rounded-xl border border-line bg-foam p-4"><span class="title-icon bg-white"><?= U::icon('shield','size-5') ?></span><p class="text-sm">Driver profiles are registered and maintained by their assigned station administrators.</p></div>
